function toWordCues(text, charStarts) {
  const cues = [];
  let i = 0;
  for (const word of text.split(/\s+/)) {
    const start = charStarts[i];
    i += word.length + 1; // +1 for space
    const end = charStarts[i] ?? charStarts[charStarts.length - 1];
    cues.push({ word, start, end });
  }
  return cues;
}
